import math

def is_power_of_5(X):
    """Checks if X is a positive integer power of 5."""
    if X <= 0:
        return False
    if X == 1:
        return True

    # Check divisibility by 5 repeatedly
    while X > 1 and X % 5 == 0:
        X //= 5

    return X == 1

# Define the search range and candidates
N_MAX = 100
candidates = [n for n in range(3, N_MAX + 1) if n % 4 == 3]

solutions = []

print(f"Starting search for n in {candidates} where 2^n - 3 is a power of 5.")

for n in candidates:
    # Calculate 2^n - 3. Since n goes up to 99, 2^99 is large, Python handles large integers automatically.
    X = pow(2, n) - 3

    if is_power_of_5(X):
        # Calculate the exponent k for reporting (optional but helpful)
        # k = log5(X)
        k = round(math.log(X) / math.log(5))

        # Double check the power using the calculated k
        if pow(5, k) == X:
            solutions.append((n, k))
            print(f"Solution found: n={n}, 2^n - 3 = 5^{k}")
        else:
            print(f"Warning: Failed power check for n={n}. Calculated k={k}, but 5^{k} != X.")

print("\n--- Summary ---")
if solutions:
    print("Confirmed solutions (n, k):")
    for sol in solutions:
        print(f"n={sol[0]}, k={sol[1]}")
else:
    print("No solutions found in the specified range.")
